class Solution:
    def minMaxWeight(self, n: int, edges: List[List[int]], threshold: int) -> int:
        # threshold is irrelevant for the answer, but kept for signature
        # collect distinct weights
        weights = sorted({w for _, _, w in edges})

        # helper: can we make 0 reachable from everyone using only edges with w <= limit ?
        def reachable(limit: int) -> bool:
            adj = [[] for _ in range(n)]          # reversed graph
            for a, b, w in edges:
                if w <= limit:
                    adj[b].append(a)              # reverse direction
            q = deque([0])
            seen = [False] * n
            seen[0] = True
            cnt = 1
            while q:
                v = q.popleft()
                for nxt in adj[v]:
                    if not seen[nxt]:
                        seen[nxt] = True
                        cnt += 1
                        q.append(nxt)
            return cnt == n

        # if even the largest weight does not work -> impossible
        if not reachable(weights[-1]):
            return -1

        # binary search for minimal feasible weight
        lo, hi = 0, len(weights) - 1
        while lo < hi:
            mid = (lo + hi) // 2
            if reachable(weights[mid]):
                hi = mid
            else:
                lo = mid + 1
        return weights[lo]

