    def countMentions(self, numberOfUsers: int, events: List[List[str]]) -> List[int]:
        # each entry = (time, priority, (kind, data))
        # priority: 0 = online, 1 = offline, 2 = message
        timeline = []

        for ev in events:
            typ = ev[0]
            ts = int(ev[1])
            if typ == "OFFLINE":
                uid = int(ev[2])
                # user goes offline now
                timeline.append((ts, 1, ("offline", uid)))
                # user comes back online after exactly 60 time units
                timeline.append((ts + 60, 0, ("online", uid)))
            else:   # MESSAGE
                mentions_str = ev[2]
                timeline.append((ts, 2, ("message", mentions_str)))

        # sort by timestamp, then by priority (online → offline → message)
        timeline.sort(key=lambda x: (x[0], x[1]))

        online = [True] * numberOfUsers
        mentions = [0] * numberOfUsers

        for _, _, (kind, data) in timeline:
            if kind == "online":
                online[data] = True
            elif kind == "offline":
                online[data] = False
            else:   # message
                tokens = data.strip().split()
                for token in tokens:
                    if token == "ALL":
                        for i in range(numberOfUsers):
                            mentions[i] += 1
                    elif token == "HERE":
                        for i in range(numberOfUsers):
                            if online[i]:
                                mentions[i] += 1
                    elif token.startswith("id"):
                        uid = int(token[2:])   # drop the leading "id"
                        mentions[uid] += 1
                    # any other token is ignored (does not occur per spec)

        return mentions

