class Solution:
    def distanceSum(self, m: int, n: int, k: int) -> int:
        N = m * n
        # ---------- factorials ----------
        fact = [1] * (N + 1)
        for i in range(1, N + 1):
            fact[i] = fact[i - 1] * i % MOD
        inv_fact = [1] * (N + 1)
        inv_fact[N] = pow(fact[N], MOD - 2, MOD)
        for i in range(N, 0, -1):
            inv_fact[i - 1] = inv_fact[i] * i % MOD

        def comb(a: int, b: int) -> int:
            if b < 0 or b > a:
                return 0
            return fact[a] * inv_fact[b] % MOD * inv_fact[a - b] % MOD

        # ---------- S(r) = (r-1)*r*(r+1)//6 ----------
        def S(r: int) -> int:
            return (r - 1) * r * (r + 1) // 6

        total_pair_distance = (
            (S(m) % MOD) * (n % MOD) % MOD * (n % MOD) % MOD +
            (S(n) % MOD) * (m % MOD) % MOD * (m % MOD) % MOD
        ) % MOD

        ways = comb(N - 2, k - 2)        # C(N-2, k-2)
        ans = ways * total_pair_distance % MOD
        return ans

