    def hasSameDigits(self, s: str) -> bool:
        """
        Repeatedly replace the string with the sums modulo 10 of each adjacent pair
        until only two digits remain. Return True if those two digits are equal.
        """
        # If the input already has two digits, just compare them
        if len(s) == 2:
            return s[0] == s[1]

        # Work with a mutable list of integer digits for efficiency
