        while len(digits) > 2:
            # Compute next level of digits
            next_digits = [
                (digits[i] + digits[i + 1]) % 10
                for i in range(len(digits) - 1)
            ]
            digits = next_digits

        # At this point we have exactly two digits
        return digits[0] == digits[1]

