class Solution:
    def maxProduct(self, nums: List[int], k: int, limit: int) -> int:
        # dp[(parity, sum)] = set of reachable products (<= limit)
        dp = dict()                       # start with empty dictionary

        for x in nums:
            new_dp = defaultdict(set)

            # 1) keep old states (skip current element)
            for (par, s), prods in dp.items():
                new_dp[(par, s)].update(prods)

            # 2) start a new subsequence with only x
            if x <= limit:
                new_dp[(1, x)].add(x)     # after first element parity = 1

            # 3) extend existing subsequences
            for (par, s), prods in dp.items():
                sign = 1 if par == 0 else -1
                new_par = 1 - par
                new_s = s + sign * x
                for p in prods:
                    new_p = p * x
                    if new_p <= limit:
                        new_dp[(new_par, new_s)].add(new_p)

            dp = new_dp

        # gather all products whose alternating sum equals k
        best = -1
        for (par, s), prods in dp.items():
            if s == k:
                if prods:
                    best = max(best, max(prods))

        return best

