class Solution:
    def numOfUnplacedFruits(self, fruits: List[int], baskets: List[int]) -> int:
        n = len(fruits)
        # ------- segment tree ----------
        size = 4 * n
        seg = [0] * size               # max capacity in the interval

        def build(node: int, l: int, r: int) -> None:
            if l == r:
                seg[node] = baskets[l]
                return
            mid = (l + r) // 2
            build(node * 2, l, mid)
            build(node * 2 + 1, mid + 1, r)
            seg[node] = max(seg[node * 2], seg[node * 2 + 1])

        def update(node: int, l: int, r: int, idx: int) -> None:
            """set basket idx capacity to 0 (mark as used)"""
            if l == r:
                seg[node] = 0
                return
            mid = (l + r) // 2
            if idx <= mid:
                update(node * 2, l, mid, idx)
            else:
                update(node * 2 + 1, mid + 1, r, idx)
            seg[node] = max(seg[node * 2], seg[node * 2 + 1])

        def find_leftmost(node: int, l: int, r: int, need: int) -> int:
            """return smallest index >= l with capacity >= need, -1 if none"""
            if seg[node] < need:
                return -1
            if l == r:
                return l
            mid = (l + r) // 2
            if seg[node * 2] >= need:
                return find_leftmost(node * 2, l, mid, need)
            else:
                return find_leftmost(node * 2 + 1, mid + 1, r, need)

        # build once
        build(1, 0, n - 1)

        unplaced = 0
        for f in fruits:
            idx = find_leftmost(1, 0, n - 1, f)
            if idx == -1:
                unplaced += 1
            else:
                update(1, 0, n - 1, idx)

        return unplaced

