def build_400_numbers(limit_root: int = 10**6):
    """return sorted list of all N = R^2 (R <= limit_root) where R has exactly
       two distinct prime factors."""
    n = limit_root
    spf = [0] * (n + 1)                # smallest prime factor
    for i in range(2, n + 1):
        if spf[i] == 0:                # i is prime
            spf[i] = i
            if i * i <= n:
                step = i
                start = i * i
                for j in range(start, n + 1, step):
                    if spf[j] == 0:
                        spf[j] = i

    result = []
    for num in range(2, n + 1):
        temp = num
        distinct = 0
        while temp > 1:
            p = spf[temp]
            distinct += 1
            while temp % p == 0:
                temp //= p
            if distinct > 2:
                break
        if distinct == 2:
            result.append(num * num)   # square, fits into 64‑bit
    return result


